using System.Collections.Generic;
using System.Threading.Tasks;

public static class Streams
{
    public static async IAsyncEnumerable<int> CountAsync(int limit)
    {
        for (var index = 0; index < limit; index++)
        {
            await Task.Delay(10);
            yield return index;
        }
    }
}

using System.Collections.Generic;

public static class Collections
{
    public static int[] Merge(int[] first, int[] second) => [.. first, .. second];

    public static int Head(int[] values)
    {
        if (values is [var first, ..])
            return first;

        return 0;
    }

    public static List<string> Names() => ["Virgo", "星空 🌌"];
}

using System.Collections.Generic;

public interface IStore<T> where T : notnull
{
    T Get(string key);
}

public sealed class MemoryStore<T> : IStore<T> where T : notnull
{
    private readonly Dictionary<string, T> entries = new();

    public void Set(string key, T value) => entries[key] = value;
    public T Get(string key) => entries[key];
}

using System;
using System.Collections.Generic;

namespace Virgo.Examples;

public sealed class Greeter(string greeting)
{
    public string Greeting { get; } = greeting;

    public void Welcome(IEnumerable<string> names)
    {
        foreach (var name in names)
        {
            Console.WriteLine($"{Greeting}, {name}!");
        }
    }
}

#nullable enable
using System;

[Flags]
public enum Permission { None = 0, Read = 1, Write = 2 }

public sealed class Options
{
    public required string Name { get; init; }
    public string? Description { get; set; }
    public Permission Access { get; init; } = Permission.Read;

    public string Label() => Description?.Trim() ?? Name;
}

using System.Linq;

public record Product(string Name, decimal Price, bool Available);

public static class Catalog
{
    public static object Search(Product[] products)
    {
        var query = from product in products
                    where product.Available && product.Price < 100m
                    orderby product.Name
                    select new { product.Name, product.Price };

        return query.ToArray();
    }
}

public record User(string Name, int Score)
{
    public bool IsActive => Score > 0;
}

public readonly record struct Position(double X, double Y);

public static class UserDisplay
{
    public static string Describe(User user) => user switch
    {
        { Score: >= 100, Name: var name } => $"Expert: {name}",
        { Score: > 0 } => "Active",
        _ => "Waiting"
    };
}

public static class Templates
{
    public static string Render(string title)
    {
        var card = $$"""
            <article class="code-card">
                <h2>{{title}}</h2>
                <!-- This stays inside the C# string. -->
            </article>
            """;

        var path = @"C:\Projects\Examples";
        return card + $"\nSource: {path}";
    }
}
